_sources = {'reference.py': '"""K Pro correction laboratory. Experimental, NOT a promoted submission.\nBased on immutable K Pro 3 (55e4655b46896f1f4c0817eda9b38204b17bb8647d634034aadcdc48d65df97d).\nIndependent switches permit paired ablation; public observations only.\n"""\nimport math\nimport copy\nCFG = {\'early_melon_delivery\': True, \'idle_overflow_delivery\': True, \'project_market\': False, \'wheat_autonomy\': False, \'melon_replant_roi\': False, \'fourth_quadrant\': False, \'near_opening_melons\': True}\nCROP = {\'WHEAT\': (10, 2, 4, 0, 6), \'CARROT\': (20, 2, 3, 0, 4), \'TOMATO\': (50, 8, 8, 1, 4), \'STRAWBERRY\': (100, 10, 10, 2, 4), \'MELON\': (80, 10, 12, 0, 6)}\nANIMAL = {\'COW\': (400, 8, 2, 6, \'MILK\'), \'SHEEP\': (500, 6, 3, 6, \'WOOL\'), \'GOOSE\': (300, 4, 1, 4, \'EGG\')}\nPARAMS = {\'WHEAT\': (25, 400, \'sqrt\', 0.8, \'log\', 0.2), \'CARROT\': (35, 450, \'hinge\', 1, \'sqrt\', 0.7), \'TOMATO\': (60, 200, \'hinge\', 0.4, \'sqrt\', 0.6), \'STRAWBERRY\': (120, 100, \'sqrt\', 0.7, \'linear\', 1.6), \'MELON\': (250, 300, \'log\', 0.2, \'sq\', 3.6), \'EGG\': (50, 332, \'hinge\', 0.4, \'log\', 0.2), \'MILK\': (160, 122, \'sqrt\', 0.6, \'linear\', 1.6), \'WOOL\': (200, 105, \'log\', 0.2, \'sq\', 3.2), \'FERTILIZER\': (100, 200, \'linear\', 0.4, \'linear\', 0.4)}\nSHOP = {\'BAKERY\': (\'EGG\', \'WHEAT\'), \'PIZZA_SHOP\': (\'MILK\', \'TOMATO\', \'WHEAT\'), \'BRUNCH_SPOT\': (\'EGG\', \'WHEAT\', \'STRAWBERRY\'), \'YARN_STORE\': (\'WOOL\', \'WOOL\'), \'ICE_CREAM_SHOP\': (\'STRAWBERRY\', \'MILK\', \'WHEAT\'), \'PET_CAFE\': (\'CARROT\', \'CARROT\'), \'SMOOTHIE_SHOP\': (\'STRAWBERRY\', \'MILK\'), \'FARMERS_MARKET\': (\'WHEAT\', \'CARROT\', \'TOMATO\', \'STRAWBERRY\')}\nSHED = ((4, 4), (5, 4), (4, 5), (5, 5))\n_STATE = {}\n_SHED_AXIS_DISTANCE = (4, 3, 2, 1, 0, 0, 1, 2, 3, 4)\n\ndef shape(kind, x, t):\n    if kind == \'sqrt\':\n        return math.sqrt(x)\n    if kind == \'log\':\n        return math.log1p(x)\n    if kind == \'sq\':\n        return x * x\n    if kind == \'hinge\':\n        u = x / t\n        return u + 8 * max(0, u - 1) ** 2\n    return x\n\ndef price(item, inventory):\n    base, t, bf, bt, af, at = PARAMS[item]\n    if inventory < 10000:\n        v = base + base * bt * shape(bf, 10000 - inventory, t) / shape(bf, t, t)\n    else:\n        v = base - base * at * shape(af, inventory - 10000, t) / shape(af, t, t)\n    return max(1, round(v))\n\ndef distance(a, b):\n    return abs(a[0] - b[0]) + abs(a[1] - b[1])\n\ndef radius(p):\n    return _SHED_AXIS_DISTANCE[p[0]] + _SHED_AXIS_DISTANCE[p[1]]\n\ndef move(p, q):\n    if p[0] != q[0]:\n        return [\'EAST\' if p[0] < q[0] else \'WEST\']\n    if p[1] != q[1]:\n        return [\'SOUTH\' if p[1] < q[1] else \'NORTH\']\n    return [\'PASS\']\n\ndef kind(t):\n    if t is None:\n        return \'EMPTY\'\n    if t == \'LOCKED\':\n        return \'LOCKED\'\n    return t.get(\'animal\') or t.get(\'crop\') or t.get(\'kind\', \'EMPTY\')\n\ndef demand(town, item):\n    return (item != \'FERTILIZER\') + 6 * sum((SHOP.get(s, ()).count(item) for s in town.get(\'unlocked_shops\', [])))\n\ndef counts(farm):\n    out = {}\n    for row in farm[\'tiles\']:\n        for t in row:\n            k = kind(t)\n            out[k] = out.get(k, 0) + 1\n    return out\n\ndef fibonacci(n):\n    a, b = (1, 1)\n    for _ in range(n):\n        a, b = (b, a + b)\n    return a\n\ndef forecast(obs, item, horizon=5):\n    """Conservative public supply estimate, not hidden future-shop prediction."""\n    current = obs[\'market\'][\'inventory\'][item]\n    supply = 0.0\n    for farm in obs[\'farms\']:\n        for row in farm[\'tiles\']:\n            for t in row:\n                if not isinstance(t, dict):\n                    continue\n                a = t.get(\'animal\')\n                if a and ANIMAL[a][4] == item:\n                    first = t[\'placed_day\'] + ANIMAL[a][1]\n                    start = max(obs[\'day\'], first)\n                    supply += max(0, (obs[\'day\'] + horizon - start) / ANIMAL[a][2]) * min(ANIMAL[a][3], 1 + ANIMAL[a][2])\n                    supply += t.get(\'yield_units\', 0)\n                if t.get(\'crop\') == item:\n                    cd = CROP[item]\n                    age = obs[\'day\'] - t[\'planted_day\']\n                    if age + horizon >= cd[1]:\n                        supply += min(cd[4], t.get(\'yield_units\', 0) + horizon / (cd[3] or 4) * 2)\n    return price(item, current + int(supply) - demand(obs.get(\'town\', {}), item) * horizon)\n\ndef plan(obs, st):\n    day = obs[\'day\']\n    me = obs[\'farms\'][obs[\'player\']]\n    priv = obs[\'private\']\n    ct = counts(me)\n    p = obs[\'market\'][\'prices\']\n    town = obs.get(\'town\', {})\n    money = me[\'money\']\n    q = len(me[\'unlocked_quadrants\'])\n    pending = {a: priv[\'shed\'].get(a, 0) + sum((i.get(a, 0) for i in priv[\'inventories\'])) for a in ANIMAL}\n    animal_n = sum((ct.get(a, 0) + pending[a] for a in ANIMAL))\n    targets = {a: ct.get(a, 0) + pending[a] for a in ANIMAL}\n    if day == 0:\n        targets[\'SHEEP\'] = 4\n        targets[\'COW\'] = 0\n    elif day <= 16:\n        limit = min(18, 4 + 0 + max(0, day - 1) * 2)\n        if money > 400 and animal_n < limit:\n            choices = []\n            species_room = {a: limit - animal_n for a in ANIMAL}\n            for a, data in ANIMAL.items():\n                if a == \'GOOSE\' and ct.get(a, 0) + pending[a] >= 2:\n                    continue\n                if a == \'GOOSE\' and demand(town, \'EGG\') < 0:\n                    continue\n                if a == \'GOOSE\':\n                    species_room[a] = 2 - ct.get(a, 0) - pending[a]\n                if a in (\'COW\', \'SHEEP\'):\n                    rival = counts(obs[\'farms\'][1 - obs[\'player\']])\n                    milk_share = max(0.3, min(0.7, 0.5 + 0.012 * (demand(town, \'MILK\') - demand(town, \'WOOL\')) + (-0.02 if day >= 1 else -0.02) * (rival.get(\'COW\', 0) - rival.get(\'SHEEP\', 0))))\n                    share = milk_share if a == \'COW\' else 1 - milk_share\n                    species_room[a] = math.ceil(18 * share) - ct.get(a, 0) - pending[a]\n                    if species_room[a] <= 0:\n                        continue\n                cost, first, interval, cap, product = data\n                ticks = max(0, (29 - day - first) // interval + 1)\n                fw = 0.35\n                fp = fw * forecast(obs, product, 8) + (1 - fw) * (0.6 * p[product] + 0.4 * PARAMS[product][0])\n                net = ticks * (interval + 1) * fp + (29 - day) * min(15, p[\'FERTILIZER\']) - (29 - day) * p[\'WHEAT\'] - cost\n                net -= (29 - day) * (2 + 1 / interval) * 0.0\n                if a in (\'COW\', \'SHEEP\'):\n                    fullness = (ct.get(a, 0) + pending[a]) / max(1, math.ceil(18 * share))\n                    net *= max(0.1, 1 - 0.6 * fullness)\n                choices.append((net / max(1, cost), a))\n            if choices:\n                value, a = max(choices)\n                if value > 1.0:\n                    targets[a] += min(2, limit - animal_n, species_room[a])\n    pending = {a: priv[\'shed\'].get(a, 0) + sum((i.get(a, 0) for i in priv[\'inventories\'])) for a in ANIMAL}\n    for a in ANIMAL:\n        targets[a] = max(targets[a], ct.get(a, 0) + pending[a])\n    herd = sum(targets.values())\n    wheat_floor = 7 if day == 0 or None is None else None\n    wheat_target = min(24, max(wheat_floor, math.ceil(herd * 0.65))) if day <= 25 else 0\n    if CFG[\'wheat_autonomy\']:\n        stock = priv[\'shed\'].get(\'WHEAT\', 0) + sum(i.get(\'WHEAT\', 0) for i in priv[\'inventories\'])\n        wheat_target = wheat_acreage_target(day, herd, wheat_stock=stock)\n    if st.get(\'terminal_active\', False) and 22 <= day <= 26:\n        wheat_target = max(wheat_target, 36)\n    straw_target = 0 if day < 3 else min(42, 2 + day * 3)\n    if day > 16:\n        straw_target = ct.get(\'STRAWBERRY\', 0)\n    if day >= 3 and forecast(obs, \'STRAWBERRY\', 8) < 20:\n        straw_target = min(straw_target, 8)\n    melon_target = 8 if day == 0 else ct.get(\'MELON\', 0)\n    if 11 <= day <= 18 and forecast(obs, \'MELON\', 10) > 100:\n        melon_target = max(melon_target, 4)\n    if CFG[\'melon_replant_roi\'] and day > 0:\n        workload = 4.8 * animal_n + 1.7 * sum(ct.get(c, 0) for c in CROP)\n        spare = max(0, (len(me[\'hands\']) + 1) * 20 - workload) * 10\n        new_melons = late_melon_plant_count(day, forecast(obs, \'MELON\', 10),\n            money, 500 + 2 * herd * p[\'WHEAT\'], available_actions=spare,\n            maximum=max(0, 4 - ct.get(\'MELON\', 0)))\n        melon_target = ct.get(\'MELON\', 0) + new_melons\n    carrot_target = 0 if day == 0 else 0\n    if 20 <= day <= 26 and p[\'CARROT\'] > 35:\n        carrot_target = min(20, 8 + int(demand(town, \'CARROT\') / 2))\n    if st.get(\'terminal_active\', False) and day >= 22 and True:\n        carrot_target = 0\n    tomato_target = ct.get(\'TOMATO\', 0)\n    if day < 20 and 4 * p[\'TOMATO\'] >= 5 * PARAMS[\'TOMATO\'][0]:\n        tomato_target = max(tomato_target, 2)\n    wanted = {\'WHEAT\': wheat_target, \'STRAWBERRY\': straw_target, \'MELON\': melon_target, \'TOMATO\': tomato_target, \'CARROT\': carrot_target}\n    roles = {}\n    for y, row in enumerate(me[\'tiles\']):\n        for x, t in enumerate(row):\n            k = kind(t)\n            if k in ANIMAL or k in CROP:\n                roles[x, y] = k\n    free = [(x, y) for y, row in enumerate(me[\'tiles\']) for x, t in enumerate(row) if kind(t) in (\'EMPTY\', \'WEED\', \'PASTURE\', \'COOP\')]\n    free.sort(key=lambda pos: (radius(pos), pos[1], pos[0]))\n    for a in (\'SHEEP\', \'COW\', \'GOOSE\'):\n        for _ in range(max(0, targets[a] - ct.get(a, 0))):\n            structure = \'COOP\' if a == \'GOOSE\' else \'PASTURE\'\n            eligible = [pos for pos in free if kind(me[\'tiles\'][pos[1]][pos[0]]) in (\'EMPTY\', \'WEED\', structure)]\n            if a != \'COW\':\n                central_sheep = any((r == \'SHEEP\' and radius(p) == 0 for p, r in roles.items()))\n                if a == \'GOOSE\' or central_sheep:\n                    noncentral = [p for p in eligible if radius(p) > 0]\n                    if noncentral:\n                        eligible = noncentral\n            if not eligible:\n                break\n            slot = min(eligible, key=lambda pos: (0 if kind(me[\'tiles\'][pos[1]][pos[0]]) == structure else 1, radius(pos), pos))\n            roles[slot] = a\n            free.remove(slot)\n    if day <= 16:\n        occupied_animals = [p for p, r in roles.items() if r in ANIMAL]\n        future = max(0, 18 - len(occupied_animals))\n        reserved_ring = [p for p in free if radius(p) <= 2][:future]\n        free = [p for p in free if p not in reserved_ring]\n    elif day < 6:\n        protected = max(0, 2 - (herd - 4 - 0))\n        free = free[protected:]\n    crop_order = (\'MELON\', \'WHEAT\', \'TOMATO\', \'STRAWBERRY\', \'CARROT\')\n    for c in crop_order:\n        for _ in range(max(0, wanted.get(c, 0) - ct.get(c, 0))):\n            allowed = [pos for pos in free if kind(me[\'tiles\'][pos[1]][pos[0]]) not in (\'PASTURE\', \'COOP\') and (q < 3 or radius(pos) <= 6)]\n            if not allowed:\n                break\n            slot = min(allowed, key=lambda pos: (-radius(pos) if c == \'MELON\' and day < 2 and not CFG[\'near_opening_melons\'] else radius(pos), pos))\n            roles[slot] = c\n            free.remove(slot)\n    workload = sum((4.8 if k in ANIMAL else 1.7 for k in roles.values()))\n    hands = min(10, max(3, math.ceil(workload / 13)))\n    if day == 0:\n        hands = 6\n    if day >= 28:\n        hands = max(3, min(10, math.ceil(workload / 15)))\n    st.update(day=day, roles=roles, herd=targets, hands=hands, targets={}, zones=None, quadrants=q)\n    if CFG[\'melon_replant_roi\']:\n        st[\'new_melon_positions\'] = {pos for pos, role in roles.items()\n            if role == \'MELON\' and kind(me[\'tiles\'][pos[1]][pos[0]]) != \'MELON\'}\n\ndef crop_tasks(t, day, prices, rotation_active=False):\n    c = t[\'crop\']\n    seed, first, maximum, interval, cap = CROP[c]\n    age = day - t[\'planted_day\']\n    yu = t.get(\'yield_units\', 0)\n    acts = []\n    dying = t.get(\'consecutive_unwatered\', 0) >= 1\n    growing = (maximum + 1) // 2 <= age <= maximum and yu < cap if not interval else age + 1 >= first and (age + 1 - first) % interval == 0 and ((age + 1 - first) // interval < cap)\n    expired = t.get(\'max_lifespan_step\', -1) >= 0\n    wheat_harvest = min(5, 5) if day <= 4 else 5\n    if c == \'WHEAT\' and rotation_active and (day >= 28):\n        wheat_harvest = min(wheat_harvest, 3)\n    ready = age >= first and yu > 0 and (interval and (yu >= 2 or expired or day == 29) or (not interval and (yu >= cap or age >= maximum or (c == \'WHEAT\' and yu >= wheat_harvest) or (day == 29))))\n    if day < 29 or ready or (not interval and age >= first and (yu > 0)):\n        wants_fert = growing and t.get(\'fertilized_until_day\', -1) < day and (interval or (c == \'WHEAT\' and True))\n        if wants_fert and prices[c] * 2 > max(8, prices[\'FERTILIZER\']):\n            acts.append([\'FERTILIZE\'])\n        if not t.get(\'watered_today\') and (growing or (dying and (not ready))):\n            acts.append([\'WATER\'])\n    if ready:\n        acts.append([\'HARVEST\'])\n    value = (prices[c] * max(1, yu) + seed * 0.5) * (1.0 if c == \'MELON\' and age >= first else 1)\n    urgent = 1000 if dying and (not ready) and (day < 29) else 0\n    return (acts, value + urgent)\n\ndef animal_tasks(t, day, prices, town, care_quotes=None):\n    a = t[\'animal\']\n    _, first, interval, cap, product = ANIMAL[a]\n    yu = t.get(\'yield_units\', 0)\n    acts = []\n    if yu > 0:\n        acts.append([\'HARVEST\'])\n    if day == 29:\n        return (acts, prices[product] * yu)\n    production = day + 1 - t[\'placed_day\'] - first >= 0 and (day + 1 - t[\'placed_day\'] - first) % interval == 0\n    skip = not t.get(\'consecutive_unfed\', 0) and prices[product] * 1.5 < prices[\'WHEAT\'] and (demand(town, product) <= 1) and (not production)\n    if not t.get(\'consecutive_unfed\', 0) and demand(town, product) <= 1:\n        marginal = min(cap - 1, t.get(\'pending_care_bonus\', 0)) if production else 1.5\n        if marginal * prices[product] < prices[\'WHEAT\']:\n            skip = True\n    care_quote = prices[product] if care_quotes is None else care_quotes[product]\n    care_quote = max(care_quote, PARAMS[product][0] * 0)\n    if day == 28:\n        missed = t.get(\'consecutive_unfed\', 0)\n        if not production and (not missed or not yu) or (production and (not missed) and (not t.get(\'pending_care_bonus\', 0))):\n            skip = True\n    if not t.get(\'fed_today\') and (not skip):\n        acts.append([\'FEED\'])\n    future_ticks = (29 - t[\'placed_day\'] - first) // interval - (day - t[\'placed_day\'] - first) // interval\n    useful_care = production or t.get(\'pending_care_bonus\', 0) < cap - 1\n    if useful_care and (not t.get(\'cared_today\')) and (not skip) and (future_ticks > 0) and (care_quote > prices[\'WHEAT\'] * 0.5):\n        acts.append([\'CARE\'])\n    if t.get(\'fertilizer_available\') and prices[\'FERTILIZER\'] >= 3:\n        acts.append([\'COLLECT_FERTILIZER\'])\n    urgent = 1000 if t.get(\'consecutive_unfed\', 0) and (not t.get(\'fed_today\')) and (not skip) else 0\n    return (acts, prices[product] * max(1, yu) + urgent)\n\ndef incremental_task_value(tile, sequence, day, prices):\n    """Approximate immediate marginal goods value; no hidden future state."""\n    k = kind(tile)\n    if k not in CROP and k not in ANIMAL:\n        return None\n    ops = {a[0] for a in sequence}\n    units = tile.get(\'yield_units\', 0)\n    result = 0.0\n    if k in CROP:\n        _, first, maximum, interval, cap = CROP[k]\n        age = day - tile[\'planted_day\']\n        growing = (maximum + 1) // 2 <= age <= maximum and units < cap if not interval else age + 1 >= first and (age + 1 - first) % interval == 0 and ((age + 1 - first) // interval < cap)\n        if \'HARVEST\' in ops:\n            result += units * prices[k]\n        if \'WATER\' in ops and growing:\n            result += min(max(0, cap - units), 2 if tile.get(\'fertilized_until_day\', -1) >= day else 1) * prices[k]\n        if \'FERTILIZE\' in ops and growing:\n            result += max(0, prices[k] - prices[\'FERTILIZER\'])\n        if tile.get(\'consecutive_unwatered\', 0) and \'WATER\' in ops:\n            result += 1000\n    else:\n        _, first, interval, cap, product = ANIMAL[k]\n        production = day + 1 - tile[\'placed_day\'] - first >= 0 and (day + 1 - tile[\'placed_day\'] - first) % interval == 0\n        if \'HARVEST\' in ops:\n            result += units * prices[product]\n        if \'FEED\' in ops:\n            bonus = min(max(0, cap - 1), tile.get(\'pending_care_bonus\', 0)) if production else 0\n            result += max(0, bonus * prices[product] - prices[\'WHEAT\'])\n            if tile.get(\'consecutive_unfed\', 0):\n                result += 1000\n        if \'CARE\' in ops:\n            result += prices[product]\n        if \'COLLECT_FERTILIZER\' in ops:\n            result += prices[\'FERTILIZER\']\n    return max(1.0, result)\n\ndef tasks(obs, st):\n    day = obs[\'day\']\n    me = obs[\'farms\'][obs[\'player\']]\n    prices = obs[\'market\'][\'prices\']\n    result = {}\n    care_quotes = None\n    for pos, role in st[\'roles\'].items():\n        t = me[\'tiles\'][pos[1]][pos[0]]\n        k = kind(t)\n        if k in CROP:\n            acts, value = crop_tasks(t, day, prices, st.get(\'terminal_active\', False))\n        elif k in ANIMAL:\n            acts, value = animal_tasks(t, day, prices, obs.get(\'town\', {}), care_quotes)\n        elif k == \'WEED\':\n            acts, value = ([[\'DIG\']], 80)\n        elif k == \'EMPTY\' and role in CROP:\n            if CFG[\'melon_replant_roi\'] and role == \'MELON\' and day > 0:\n                # A harvested tile retains its old role until replanning. Do not\n                # let that stale role create an unbudgeted second wave at J10.\n                if not st.get(\'new_melon_positions\') or pos not in st[\'new_melon_positions\']:\n                    continue\n            admissible = len(me[\'unlocked_quadrants\']) < 3 or radius(pos) <= 6\n            acts, value = ([[\'PLANT\', role], [\'WATER\']], 120) if admissible and obs[\'hour\'] < 21 and (day + CROP[role][1] < 30) else ([], 0)\n        elif k == \'EMPTY\' and role in ANIMAL:\n            acts, value = ([[\'BUILD_COOP\' if role == \'GOOSE\' else \'BUILD_PASTURE\'], [\'PLACE\', role]], 200)\n        elif k in (\'PASTURE\', \'COOP\') and role in ANIMAL:\n            acts, value = ([[\'PLACE\', role]], 200)\n        else:\n            acts, value = ([], 0)\n        if acts:\n            if day >= 6:\n                marginal = incremental_task_value(t, acts, day, prices)\n                if marginal is not None:\n                    value = (1 - 0.5) * value + 0.5 * marginal\n            result[pos] = (acts, value)\n    return result\n\ndef zone_total(values):\n    return math.fsum(values)\n\ndef assignment_urgency(value, hour, day):\n    divisor = 250 if day < 6 else 500\n    return min(8, value / divisor) * (1.8 if hour >= 17 else 1.0)\n\ndef zones(st, work, n):\n    zone_mode = \'specialized\' if st[\'day\'] >= 99 else \'angular\'\n    order = sorted(work, key=lambda p: (math.atan2(p[1] - 4.5, p[0] - 4.5), radius(p)))\n    if zone_mode == \'routing\':\n        routes = [[] for _ in range(n)]\n        duration = [2.0] * n\n        out = {}\n        for pos in sorted(work, key=lambda p: (-radius(p), -len(work[p][0]), p)):\n            service = len(work[pos][0])\n            if st[\'roles\'][pos] in ANIMAL and any((a[0] in (\'PLACE\', \'BUILD_PASTURE\', \'BUILD_COOP\') for a in work[pos][0])):\n                service += 2\n            best = None\n            for uid, route in enumerate(routes):\n                for j in range(len(route) + 1):\n                    before = route[j - 1] if j else None\n                    after = route[j] if j < len(route) else None\n                    first = distance(before, pos) if before else radius(pos)\n                    last = distance(pos, after) if after else 0\n                    old = (distance(before, after) if before else radius(after)) if after else 0\n                    delta = first + last - old + service\n                    cost = delta + 0.03 * duration[uid] + 0.8 * max(0, duration[uid] + delta - 21) ** 2\n                    choice = (cost, uid, j, delta)\n                    if best is None or choice < best:\n                        best = choice\n            _, uid, j, delta = best\n            routes[uid].insert(j, pos)\n            duration[uid] += delta\n            out[pos] = uid\n        st[\'zones\'] = out\n        st[\'zone_count\'] = n\n        st[\'planned_routes\'] = routes\n        return out\n    if zone_mode == \'specialized\' and n > 1:\n        animal = [p for p in order if st[\'roles\'][p] in ANIMAL]\n        crops = [p for p in order if st[\'roles\'][p] not in ANIMAL]\n        nh = min(n - 1, max(1, math.ceil(len(animal) * 5.0 / 22))) if animal else 0\n        if not crops:\n            nh = n\n        out = {}\n        for group, offset, size in ((animal, 0, nh), (crops, nh, n - nh)):\n            total = zone_total((len(work[p][0]) + 1.3 for p in group))\n            done = 0.0\n            for p in group:\n                out[p] = offset + min(size - 1, int(done / max(1, total) * size))\n                done += len(work[p][0]) + 1.3\n        st[\'zones\'] = out\n        st[\'zone_count\'] = n\n        return out\n    if zone_mode == \'strips\':\n        order = sorted(work, key=lambda p: (p[0] // 2, p[1] if p[0] // 2 % 2 == 0 else -p[1], p[0]))\n    total = zone_total((len(work[p][0]) + 1.3 for p in order))\n    done = 0.0\n    out = {}\n    for p in order:\n        out[p] = min(n - 1, int(done / max(1, total) * n))\n        done += len(work[p][0]) + 1.3\n    st[\'zones\'] = out\n    st[\'zone_count\'] = n\n    return out\n\ndef act_units_greedy(obs, st, work):\n    me = obs[\'farms\'][obs[\'player\']]\n    priv = obs[\'private\']\n    hour = obs[\'hour\']\n    day = obs[\'day\']\n    positions = [tuple(me[\'farmer\'])] + [tuple(p) for p in me[\'hands\']]\n    inventories = priv[\'inventories\']\n    shed = dict(priv[\'shed\'])\n    seeds = dict(priv[\'seeds\'])\n    n = len(positions)\n    z = st.get(\'zones\')\n    planned = max(n, st.get(\'hands\', n - 1) + 1)\n    if z is None or st.get(\'zone_count\') != planned:\n        z = zones(st, work, planned)\n    reserved = set()\n    actions = []\n    fixed = set()\n    st[\'_fixed_units\'] = fixed\n    owners = {p: u for u, p in st[\'targets\'].items() if u < n and p in work}\n    deadline = 23 if day == 29 else 24\n    for uid, pos in enumerate(positions):\n        inv = inventories[uid] if uid < len(inventories) else {}\n        nearest = min(SHED, key=lambda s: distance(pos, s))\n        back = distance(pos, nearest)\n        sellable = sum((inv.get(p, 0) for p in PARAMS))\n        if day == 29 and sellable and (hour + back + 1 >= deadline):\n            action = [\'DROP\'] if back == 0 else move(pos, nearest)\n            if back == 0:\n                room = 100 - sum(shed.values())\n                for item, count in inv.items():\n                    add = max(0, min(count, room))\n                    shed[item] = shed.get(item, 0) + add\n                    room -= add\n            actions.append(action)\n            fixed.add(uid)\n            continue\n        premium = [p for p in PARAMS if p not in (\'WHEAT\', \'FERTILIZER\') and inv.get(p, 0) > 0]\n        early_fert = False\n        if early_fert and inv.get(\'FERTILIZER\', 0):\n            premium.append(\'FERTILIZER\')\n        cash_item = max(premium, key=lambda p: inv[p] * obs[\'market\'][\'prices\'][p], default=None)\n        cash_value = inv.get(cash_item, 0) * obs[\'market\'][\'prices\'].get(cash_item, 0)\n        standing = me[\'tiles\'][pos[1]][pos[0]]\n        service_pending = day >= 99 and any((a[0] == \'WATER\' and kind(standing) in CROP or (a[0] == \'FEED\' and inv.get(\'WHEAT\', 0) > 0) or (a[0] == \'CARE\' and isinstance(standing, dict) and standing.get(\'fed_today\')) for a in work.get(pos, ([], 0))[0]))\n        central_sale = back == 0 and cash_value >= (min(70, 200) if early_fert else 200 if day >= 12 else 200) and (cash_item is not None)\n        capital_due = day <= 12 and me[\'money\'] < 4000 and (hour < 18)\n        deliver = central_sale or (capital_due and cash_value >= (min(120, 400) if early_fert else 400) + back * 50 and (back <= 4) and (hour + back + 1 < 24))\n        # Sell the first wave before waiting for automatic night deposit. Never\n        # start a route that cannot deposit this day; protect urgent local care.\n        urgent_here = any(a[0] in (\'WATER\', \'FEED\') for a in work.get(pos, ([], 0))[0])\n        if (CFG[\'early_melon_delivery\'] and day in (10, 11)\n                and cash_item == \'MELON\' and hour + back < 24\n                and cash_value >= 200 + 50 * (back + 1) and not urgent_here):\n            deliver = True\n        if cash_item and (not service_pending) and deliver:\n            if back:\n                actions.append(move(pos, nearest))\n                fixed.add(uid)\n                continue\n            amount = min(inv[cash_item], max(0, 100 - sum(shed.values())))\n            if amount:\n                actions.append([\'PLACE\', cash_item, amount])\n                shed[cash_item] = shed.get(cash_item, 0) + amount\n                fixed.add(uid)\n                continue\n        if back == 0 and sum((inv.get(p, 0) for p in premium)) >= 12 and (hour > 7 or day == 29):\n            room = 100 - sum(shed.values())\n            if room >= sellable:\n                for item, count in inv.items():\n                    shed[item] = shed.get(item, 0) + count\n                actions.append([\'DROP\'])\n                fixed.add(uid)\n                continue\n        own = [p for p in work if z.get(p) == uid]\n        feed_need = sum((any((a[0] == \'FEED\' for a in work[p][0])) for p in own))\n        if feed_need:\n            feed_need += 0\n        fert_need = sum((any((a[0] == \'FERTILIZE\' for a in work[p][0])) for p in own))\n        if back == 0:\n            took = False\n            for item, need in [(\'WHEAT\', feed_need), (\'FERTILIZER\', min(5, fert_need))]:\n                if day >= 6 and need:\n                    batch = 0 if item == \'WHEAT\' else 0\n                    if batch:\n                        op = \'FEED\' if item == \'WHEAT\' else \'FERTILIZE\'\n                        total_need = sum((any((a[0] == op for a in todo)) for todo, _ in work.values()))\n                        already_carried = sum((i.get(item, 0) for i in inventories))\n                        already_booked = max(0, priv[\'shed\'].get(item, 0) - shed.get(item, 0))\n                        available_demand = max(0, total_need - already_carried - already_booked)\n                        need = max(need, inv.get(item, 0) + min(batch, available_demand))\n                qty = min(max(0, need - inv.get(item, 0)), shed.get(item, 0))\n                if qty and hour < 18:\n                    actions.append([\'PICKUP\', item, qty])\n                    shed[item] -= qty\n                    took = True\n                    break\n            if took:\n                fixed.add(uid)\n                continue\n            for a in ANIMAL:\n                needing = sum((st[\'roles\'][p] == a and kind(me[\'tiles\'][p[1]][p[0]]) not in ANIMAL for p in own))\n                if needing > inv.get(a, 0) and shed.get(a, 0):\n                    qty = min(needing - inv.get(a, 0), shed[a])\n                    actions.append([\'PICKUP\', a, qty])\n                    shed[a] -= qty\n                    took = True\n                    break\n            if took:\n                fixed.add(uid)\n                continue\n        best = None\n        for p, (todo, value) in work.items():\n            if p in reserved:\n                continue\n            owner = owners.get(p, uid)\n            sequence = []\n            requires = None\n            for a in todo:\n                op = a[0]\n                if op == \'FERTILIZE\' and inv.get(\'FERTILIZER\', 0) <= 0:\n                    continue\n                if op == \'FEED\' and inv.get(\'WHEAT\', 0) <= 0:\n                    requires = \'WHEAT\'\n                    continue\n                if op == \'CARE\' and (not inv.get(\'WHEAT\')) and (not me[\'tiles\'][p[1]][p[0]].get(\'fed_today\')):\n                    continue\n                if op in (\'BUILD_PASTURE\', \'BUILD_COOP\') and inv.get(st[\'roles\'][p], 0) <= 0:\n                    requires = st[\'roles\'][p]\n                    break\n                if op == \'PLACE\' and inv.get(a[1], 0) <= 0:\n                    requires = a[1]\n                    break\n                if op == \'PLANT\' and seeds.get(a[1], 0) <= 0:\n                    break\n                sequence.append(a)\n            d = distance(pos, p)\n            if not sequence:\n                if requires and shed.get(requires, 0) > 0 and (hour + back + 2 + radius(p) < deadline):\n                    score = back + radius(p) + 4 + 6 * (z.get(p) != uid)\n                    candidate = (score, p, [\'PICKUP\', requires, 1] if back == 0 else move(pos, nearest), True)\n                else:\n                    continue\n            else:\n                if day == 29 and (not any((a[0] == \'HARVEST\' for a in sequence))):\n                    continue\n                if day == 29 and True and (hour + d + len(sequence) + radius(p) + 1 > deadline):\n                    sequence = [a for a in sequence if a[0] == \'HARVEST\']\n                if hour + d + 1 + (radius(p) + 1 if day == 29 else 0) > deadline:\n                    continue\n                score = d + 6 * (z.get(p) != uid) - min(3.0, value / 600)\n                if st[\'targets\'].get(uid) == p:\n                    score -= 1.0\n                if p == pos:\n                    score -= 2.0\n                candidate = (score, p, sequence[0] if d == 0 else move(pos, p), False)\n            if best is None or (candidate[0], candidate[1]) < (best[0], best[1]):\n                best = candidate\n        if best:\n            _, target, action, supply = best\n            reserved.add(target)\n            st[\'targets\'][uid] = target\n            if supply:\n                fixed.add(uid)\n            if action[0] == \'PLANT\':\n                seeds[action[1]] -= 1\n            if action[0] == \'PICKUP\':\n                shed[action[1]] -= action[2]\n            actions.append(action)\n        else:\n            actions.append([\'PASS\'])\n    return (actions, shed)\n\ndef minimum_assignment(costs):\n    """Rectangular Hungarian assignment, deterministic ties, O(n*n*m)."""\n    n = len(costs)\n    if not n:\n        return []\n    m = len(costs[0])\n    u = [0.0] * (n + 1)\n    v = [0.0] * (m + 1)\n    p = [0] * (m + 1)\n    way = [0] * (m + 1)\n    for i in range(1, n + 1):\n        p[0] = i\n        j0 = 0\n        minimum = [float(\'inf\')] * (m + 1)\n        used = [False] * (m + 1)\n        while True:\n            used[j0] = True\n            i0 = p[j0]\n            delta = float(\'inf\')\n            j1 = 0\n            for j in range(1, m + 1):\n                if not used[j]:\n                    cur = costs[i0 - 1][j - 1] - u[i0] - v[j]\n                    if cur < minimum[j]:\n                        minimum[j] = cur\n                        way[j] = j0\n                    if minimum[j] < delta:\n                        delta = minimum[j]\n                        j1 = j\n            for j in range(m + 1):\n                if used[j]:\n                    u[p[j]] += delta\n                    v[j] -= delta\n                else:\n                    minimum[j] -= delta\n            j0 = j1\n            if p[j0] == 0:\n                break\n        while True:\n            j1 = way[j0]\n            p[j0] = p[j1]\n            j0 = j1\n            if j0 == 0:\n                break\n    answer = [-1] * n\n    for j in range(1, m + 1):\n        if p[j]:\n            answer[p[j] - 1] = j - 1\n    return answer\n\ndef act_units(obs, st, work):\n    previous_targets = dict(st[\'targets\'])\n    actions, shed = act_units_greedy(obs, st, work)\n    me = obs[\'farms\'][obs[\'player\']]\n    priv = obs[\'private\']\n    hour = obs[\'hour\']\n    day = obs[\'day\']\n    pos = [tuple(me[\'farmer\'])] + [tuple(p) for p in me[\'hands\']]\n    fixed = st[\'_fixed_units\']\n    workers = [i for i in range(len(pos)) if i not in fixed]\n    fixed_tiles = {pos[i] for i in fixed if actions[i][0] == \'PLACE\' and len(actions[i]) > 1 and (actions[i][1] in ANIMAL)}\n    tiles = sorted((p for p in work if p not in fixed_tiles))\n    costs = []\n    commands = []\n    seeds = dict(priv[\'seeds\'])\n    for uid in workers:\n        inv = priv[\'inventories\'][uid] if uid < len(priv[\'inventories\']) else {}\n        row = []\n        cmd = []\n        for p in tiles:\n            todo, value = work[p]\n            valid = []\n            for a in todo:\n                op = a[0]\n                if op == \'FERTILIZE\' and (not inv.get(\'FERTILIZER\')):\n                    continue\n                if op == \'FEED\' and (not inv.get(\'WHEAT\')):\n                    continue\n                if op == \'CARE\':\n                    t = me[\'tiles\'][p[1]][p[0]]\n                    if not t.get(\'fed_today\') and (not inv.get(\'WHEAT\')):\n                        continue\n                if op in (\'BUILD_PASTURE\', \'BUILD_COOP\') and (not inv.get(st[\'roles\'][p])):\n                    break\n                if op == \'PLACE\' and (not inv.get(a[1])):\n                    break\n                if op == \'PLANT\' and (not seeds.get(a[1])):\n                    break\n                valid.append(a)\n            d = distance(pos[uid], p)\n            deadline = 23 if day == 29 else 24\n            if day == 29 and True and (hour + d + len(valid) + radius(p) + 1 > deadline):\n                valid = [a for a in valid if a[0] == \'HARVEST\']\n            if not valid or hour + d + 1 + (radius(p) + 1 if day == 29 else 0) > deadline or (day == 29 and (not any((a[0] == \'HARVEST\' for a in valid)))):\n                row.append(1000000.0)\n                cmd.append([\'PASS\'])\n                continue\n            action = valid[0] if d == 0 else move(pos[uid], p)\n            urgency = assignment_urgency(value, hour, obs[\'day\'])\n            zone_cost = 6\n            cost = d + 0.15 * len(valid) - urgency + zone_cost * (st[\'zones\'].get(p) != uid)\n            if pos[uid] == p:\n                cost -= 2\n            if previous_targets.get(uid) == p:\n                cost -= 0.4\n            row.append(cost)\n            cmd.append(action)\n        costs.append(row + [50.0] * len(workers))\n        commands.append(cmd)\n    matched = minimum_assignment(costs)\n    for index, uid in enumerate(workers):\n        j = matched[index]\n        if j >= len(tiles) or costs[index][j] >= 100000.0:\n            actions[uid] = [\'PASS\']\n            st[\'targets\'].pop(uid, None)\n            continue\n        action = commands[index][j]\n        if action[0] == \'PLANT\':\n            crop = action[1]\n            if seeds.get(crop, 0) <= 0:\n                action = [\'PASS\']\n            else:\n                seeds[crop] -= 1\n        actions[uid] = action\n        st[\'targets\'][uid] = tiles[j]\n    return (actions, shed)\n\ndef idle_deliveries(obs, actions, shed, original_obs=None):\n    """Use otherwise idle actions to sell loads before a forecast night overflow.\n\n    Never orders a general return: at most enough idle loads to cover the excess,\n    and never steals an action already assigned to a live field task.\n    """\n    if not CFG[\'idle_overflow_delivery\'] or obs[\'hour\'] < 14:\n        return (actions, shed)\n    # Caller supplies post-unit state when projection is enabled. Only PASS\n    # commands are replaced: no feed, watering, or harvest task is stolen.\n    me = obs[\'farms\'][obs[\'player\']]\n    positions = [tuple(me[\'farmer\'])] + [tuple(p) for p in me[\'hands\']]\n    inventories = obs[\'private\'][\'inventories\']\n    excess = sum(shed.values()) + sum(sum(i.values()) for i in inventories) - 90\n    if excess <= 0:\n        return (actions, shed)\n    actions, shed = list(actions), dict(shed)\n    original_obs = obs if original_obs is None else original_obs\n    herd = sum(counts(me).get(a, 0) for a in ANIMAL)\n    food = sum(i.get(\'WHEAT\', 0) for i in inventories) + shed.get(\'WHEAT\', 0)\n    choices = []\n    for uid, (pos, inv, action) in enumerate(zip(positions, inventories, actions)):\n        if action != [\'PASS\']:\n            continue\n        nearest = min(SHED, key=lambda p: (distance(pos, p), p))\n        back = distance(pos, nearest)\n        if obs[\'hour\'] + back >= 24:\n            continue\n        for item in sorted(PARAMS):\n            qty = inv.get(item, 0)\n            if item == \'WHEAT\':\n                qty = min(qty, max(0, food - 2 * herd))\n            if item == \'FERTILIZER\':\n                qty = max(0, qty - 5)\n            if qty:\n                value = qty * obs[\'market\'][\'prices\'][item] / (back + 1)\n                choices.append((-value, back, uid, item, qty, nearest))\n    used = set()\n    for _, back, uid, item, qty, nearest in sorted(choices):\n        if excess <= 0:\n            break\n        if uid in used:\n            continue\n        room = max(0, 100 - sum(shed.values()))\n        if not room:\n            break\n        qty = min(qty, room)\n        if item == \'WHEAT\':\n            qty = min(qty, max(0, food - 2 * herd))\n        if qty <= 0:\n            continue\n        proposed = move(positions[uid], nearest) if back else [\'PLACE\', item, qty]\n        if not back:\n            # Inserting an earlier deposit must not steal room from an already\n            # assigned later DROP, nor borrow room freed only by a later PICKUP.\n            before = project_unit_phase(original_obs, actions)[\'private\']\n            trial = list(actions)\n            trial[uid] = proposed\n            after = project_unit_phase(original_obs, trial)[\'private\']\n            products = set(before[\'shed\']) | set(after[\'shed\'])\n            for inv in before[\'inventories\'] + after[\'inventories\']:\n                products.update(inv)\n            if any(after[\'shed\'].get(p, 0) + sum(i.get(p, 0) for i in after[\'inventories\'])\n                   < before[\'shed\'].get(p, 0) + sum(i.get(p, 0) for i in before[\'inventories\'])\n                   for p in products):\n                continue\n            moved = before[\'inventories\'][uid].get(item, 0) - after[\'inventories\'][uid].get(item, 0)\n            if moved <= 0:\n                continue\n            qty = moved\n            shed = dict(after[\'shed\'])\n        actions[uid] = proposed\n        used.add(uid)\n        excess -= qty\n        if item == \'WHEAT\':\n            food -= qty\n    return (actions, shed)\n\ndef market_orders(obs, st, shed):\n    me = obs[\'farms\'][obs[\'player\']]\n    priv = obs[\'private\']\n    day = obs[\'day\']\n    hour = obs[\'hour\']\n    prices = obs[\'market\'][\'prices\']\n    mi = obs[\'market\'][\'inventory\']\n    money = me[\'money\']\n    orders = []\n    ct = counts(me)\n    herd = sum((ct.get(a, 0) for a in ANIMAL))\n    carry = {p: sum((i.get(p, 0) for i in priv[\'inventories\'])) for p in PARAMS}\n    final_feeds = None\n    if day == 28:\n        final_feeds = sum((any((a[0] == \'FEED\' for a in todo)) for todo, _ in tasks(obs, st).values()))\n    projected = sum(shed.values()) + sum(carry.values())\n    items = sorted(PARAMS, key=lambda p: (-prices[p], p))\n    for item in items:\n        have = shed.get(item, 0)\n        keep = 0\n        if day < 29:\n            if item == \'WHEAT\':\n                keep = max(0, math.ceil(herd * (1.5 if hour < 16 else 0.8)) - carry[item])\n            if item == \'WHEAT\' and final_feeds is not None:\n                keep = max(0, final_feeds - carry[item])\n            if item == \'FERTILIZER\':\n                willing = prices[\'FERTILIZER\'] < prices[\'WHEAT\'] * 1.5 or day >= 9\n                keep = max(0, (12 if willing else 0) - carry[item])\n        amount = max(0, have - keep)\n        if not amount:\n            continue\n        floor = max(1, int(PARAMS[item][0] * 0.05))\n        if day >= 28 or projected > 85 or money < 300:\n            floor = 1\n        if day < 28 and hour > 2 and (item in (\'MILK\', \'WOOL\', \'STRAWBERRY\')) and (projected < 60) and (money > 1000):\n            floor = max(floor, int(forecast(obs, item, 1) * 0.8))\n        qty = 0\n        revenue = 0\n        while qty < amount and price(item, mi[item] + qty) >= floor:\n            revenue += price(item, mi[item] + qty)\n            qty += 1\n        if qty:\n            orders.append([\'SELL\', item, qty])\n            money += revenue\n            shed[item] -= qty\n\n    def append(order, cost):\n        nonlocal money\n        if len(orders) < 10 and money >= cost:\n            orders.append(order)\n            money -= cost\n            return True\n        return False\n    food_reserve = max(0, herd - shed.get(\'WHEAT\', 0) - carry[\'WHEAT\']) * prices[\'WHEAT\'] if day < 29 else 0\n    current = len(me[\'hands\'])\n    hires = me.get(\'hires_today\', current)\n    while current < st[\'hands\'] and hour < 8:\n        if money - fibonacci(hires) < food_reserve or not append([\'HIRE\'], fibonacci(hires)):\n            break\n        current += 1\n        hires += 1\n    if day == 29:\n        return orders[:10]\n    unfed = sum((1 for row in me[\'tiles\'] for t in row if isinstance(t, dict) and t.get(\'animal\') and (not t.get(\'fed_today\'))))\n    wheat_need = max(0, (unfed + sum(st[\'herd\'].values()) // 3 if final_feeds is None else final_feeds) - shed.get(\'WHEAT\', 0) - carry[\'WHEAT\'])\n    if wheat_need and hour < 19:\n        qty = wheat_need\n        while qty and sum((price(\'WHEAT\', mi[\'WHEAT\'] - i - 1) for i in range(qty))) > money - 10:\n            qty -= 1\n        if qty:\n            append([\'BUY_PRODUCT\', \'WHEAT\', qty], sum((price(\'WHEAT\', mi[\'WHEAT\'] - i - 1) for i in range(qty))))\n    reserve = 50 + max(0, herd - priv[\'shed\'].get(\'WHEAT\', 0) - carry[\'WHEAT\']) * prices[\'WHEAT\']\n    q = len(me[\'unlocked_quadrants\'])\n    land_day = 6 if q == 1 else 10 if q == 2 else 12\n    land_cost = (1000, 2000, 4000)[min(2, q - 1)]\n\n    def acquire_land():\n        eligible = q < 3\n        if CFG[\'fourth_quadrant\'] and q == 3:\n            diamond = [kind(t) for y, row in enumerate(me[\'tiles\']) for x, t in enumerate(row)\n                       if radius((x, y)) <= 6 and (x,y) not in SHED and kind(t) != \'LOCKED\']\n            occupied = sum(k in CROP or k in ANIMAL for k in diamond)\n            eligible = fourth_quadrant_eligible(day, q, money, reserve, land_cost, occupied, len(diamond))\n        if q < 4 and eligible and (land_day <= day <= 16) and (money > land_cost + reserve + 100):\n            append([\'BUY_LAND\'], land_cost)\n    acquire_land()\n    escrow = 0\n    for a, data in ANIMAL.items():\n        held = priv[\'shed\'].get(a, 0) + sum((i.get(a, 0) for i in priv[\'inventories\']))\n        need = st[\'herd\'][a] - ct.get(a, 0) - held\n        if need > 0 and hour < 14:\n            qty = min(need, max(0, int((money - reserve - escrow) // data[0])))\n            if qty:\n                append([\'BUY_ANIMAL\', a, qty], qty * data[0])\n    for crop, data in CROP.items():\n        if day + data[1] >= 30:\n            continue\n        needed = sum((role == crop and kind(me[\'tiles\'][p[1]][p[0]]) in (\'EMPTY\', \'WEED\') and (len(me[\'unlocked_quadrants\']) < 3 or radius(p) <= 6) for p, role in st[\'roles\'].items())) - priv[\'seeds\'].get(crop, 0)\n        if CFG[\'melon_replant_roi\'] and crop == \'MELON\' and day > 0:\n            needed = sum(kind(me[\'tiles\'][p[1]][p[0]]) in (\'EMPTY\', \'WEED\')\n                         for p in st.get(\'new_melon_positions\', ())) - priv[\'seeds\'].get(crop, 0)\n        if needed > 0 and hour < 18:\n            qty = min(needed, max(0, int((money - 50) // data[0])))\n            if qty:\n                append([\'BUY_SEED\', crop, qty], qty * data[0])\n    return orders[:10]\n\ndef decide(obs, st):\n    player = obs[\'player\']\n    step = obs.get(\'step\', obs[\'day\'] * 24 + obs[\'hour\'])\n    structural = st.get(\'quadrants\') != len(obs[\'farms\'][player][\'unlocked_quadrants\']) or False\n    if st[\'day\'] != obs[\'day\'] or structural or (obs[\'hour\'] in (4, 12) and obs[\'farms\'][player][\'money\'] > 400):\n        keep_routes = st.get(\'day\') == obs[\'day\'] and st.get(\'quadrants\') == len(obs[\'farms\'][player][\'unlocked_quadrants\']) and structural\n        previous = {k: st.get(k) for k in (\'zones\', \'targets\', \'zone_count\', \'hands\')}\n        stable = False\n        plan(obs, st)\n        if keep_routes:\n            st.update(previous)\n        elif stable and st[\'hands\'] == previous[\'hands\']:\n            z = dict(previous[\'zones\'])\n            anchors = list(z)\n            for pos in sorted(st[\'roles\']):\n                if pos not in z and anchors:\n                    z[pos] = z[min(anchors, key=lambda p: (distance(pos, p), p))]\n            st.update(zones=z, zone_count=previous[\'zone_count\'], targets=previous[\'targets\'])\n        st[\'rotation_pending\'] = False\n    work = tasks(obs, st)\n    actions, shed = act_units(obs, st, work)\n    if CFG[\'project_market\']:\n        projected = project_unit_phase(obs, actions)\n        actions, _ = idle_deliveries(projected, actions, projected[\'private\'][\'shed\'], original_obs=obs)\n        projected = project_unit_phase(obs, actions)\n        orders = market_orders(projected, st, dict(projected[\'private\'][\'shed\']))\n    else:\n        actions, shed = idle_deliveries(obs, actions, shed)\n        orders = market_orders(obs, st, shed)\n    st[\'last_step\'] = step\n    return {\'farmer\': actions[0], \'hands\': actions[1:], \'market\': orders}\n\ndef agent(obs, configuration=None):\n    player = obs[\'player\']\n    step = obs.get(\'step\', obs[\'day\'] * 24 + obs[\'hour\'])\n    if player not in _STATE or step <= _STATE[player].get(\'last_step\', -1):\n        _STATE[player] = {\'day\': -1}\n    st = _STATE[player]\n    return decide(obs, st)\n\n"""Bounded public-state economic guards; these are heuristics, not ROI promises."""\nimport math\n\n\ndef wheat_acreage_target(day, herd, feed_per_day=None, wheat_stock=0,\n                         renewal_days=4, yield_per_plot=5):\n    """Return desired total wheat plots, including currently planted wheat.\n\n    One feed consumes one wheat. Cover demand across a four-day harvest/renewal\n    cycle at the policy\'s five-unit harvest threshold, less accessible stock.\n    ``feed_per_day`` can reflect actual planned feeding; omitted means one per\n    target animal. Stock means own shed plus hands, never market inventory.\n    Keep K Pro 3\'s seven-plot floor and baseline, allowing at most three extra\n    plots and 24 total. This limited adjustment cannot guarantee self-sufficiency.\n    """\n    if day > 25:\n        return 0\n    herd = max(0, herd)\n    baseline = min(24, max(7, math.ceil(0.65 * herd)))\n    daily_feed = herd if feed_per_day is None else max(0, feed_per_day)\n    cycle_demand = daily_feed * max(1, renewal_days)\n    shortage = max(0, cycle_demand - max(0, wheat_stock))\n    renewal_plots = math.ceil(shortage / max(1, yield_per_plot))\n    return min(24, baseline + 3, max(baseline, renewal_plots))\n\n\ndef late_melon_plant_count(day, forecast_price, money, reserve, *,\n                          seed_cost=80, labor_cost=120, available_actions=0,\n                          actions_per_plot=16, maximum=4):\n    """Return an upper bound on NEW melon plots; never removes existing plants.\n\n    Caller supplies the public forecast at first harvest (ten days ahead), not\n    today\'s quote, and spare worker actions over that growing period after\n    existing commitments. Reserve includes feed/hiring and other commitments.\n    Require a day for sale after first harvest and restrict the late wave to\n    days 11..18. Value four units at 80% of the forecast and require revenue to\n    exceed seed plus labor opportunity cost by 25%. Cash covers both costs;\n    this intentionally conservative budget is not an estimated realized profit.\n    """\n    if day < 11 or day + 10 + 1 > 29:\n        return 0\n    cost = max(0, seed_cost) + max(0, labor_cost)\n    conservative_revenue = 4 * 0.8 * max(0, forecast_price)\n    if cost <= 0 or conservative_revenue <= cost * 1.25:\n        return 0\n    cash_plots = int(max(0, money - max(0, reserve)) // cost)\n    labor_plots = int(max(0, available_actions) // max(1, actions_per_plot))\n    return max(0, min(4, int(maximum), cash_plots, labor_plots))\n\n\ndef fourth_quadrant_eligible(day, quadrants, money, reserve, land_cost,\n                             occupied_diamond, diamond_capacity, *,\n                             expansion_budget=1000):\n    """Permit considering the fourth quadrant, never blindly force its purchase.\n\n    Count productive crop/animal tiles within radius six on currently unlocked\n    land against all usable radius-six tiles there (exclude shed and locked\n    tiles). Require 85% saturation, fourteen days left, and cash for land plus\n    current operating reserve plus an additional planting/worker allowance.\n    This checks resource feasibility; it is not proof expansion will pay back.\n    """\n    if quadrants != 3 or 29 - day < 14 or diamond_capacity <= 0:\n        return False\n    if max(0, occupied_diamond) < 0.85 * diamond_capacity:\n        return False\n    budget = max(0, land_cost) + max(0, reserve) + max(0, expansion_budget)\n    return money >= budget\n\n"""Deterministic own-unit projection for the standard 24-turn/100-capacity game.\n\nThis is the state immediately before market processing, not the next observation:\ntime, market, opponents, decay, night refresh and randomness are not advanced.\n"""\nimport copy\n\n\n_PRO4_CROPS = {\n    # first harvest age, last yield age, maximum yield, ongoing\n    \'WHEAT\': (2, 4, 6, False), \'CARROT\': (2, 3, 4, False),\n    \'TOMATO\': (8, 8, 4, True), \'STRAWBERRY\': (10, 10, 4, True),\n    \'MELON\': (10, 12, 6, False),\n}\n_PRO4_ANIMALS = {\'GOOSE\': (\'COOP\', \'EGG\'), \'COW\': (\'PASTURE\', \'MILK\'),\n                 \'SHEEP\': (\'PASTURE\', \'WOOL\')}\n\n\ndef project_unit_phase(obs, actions):\n    """Copy and apply selected [farmer, *hands] actions in canonical order.\n\n    Only public state and this player\'s private state are needed. As in the\n    interpreter, oversubscribed seed requests all fail atomically. Inputs are\n    engine-valid observations and action lists; configuration is the standard\n    KPro game (24 turns/day, shed capacity 100).\n    """\n    result = dict(obs)\n    result[\'private\'] = copy.deepcopy(obs[\'private\'])\n    result[\'farms\'] = list(obs[\'farms\'])\n    farm = copy.deepcopy(obs[\'farms\'][obs[\'player\']])\n    result[\'farms\'][obs[\'player\']] = farm\n    private = result[\'private\']\n    shed, seeds = private[\'shed\'], private[\'seeds\']\n    # Nonzero seats can receive only day/hour, without the framework\'s step.\n    step = obs.get(\'step\')\n    if step is None:\n        step = obs[\'day\'] * 24 + obs.get(\'hour\', 0)\n    day = step // 24\n    size = len(farm[\'tiles\'])\n    half = size // 2\n    access = {(half - 1, half - 1), (half, half - 1),\n              (half - 1, half), (half, half)}\n    moves = {\'NORTH\': (0, -1), \'SOUTH\': (0, 1),\n             \'WEST\': (-1, 0), \'EAST\': (1, 0)}\n    demand = {}\n    for action in actions:\n        if isinstance(action, list) and len(action) >= 2 and action[0] == \'PLANT\':\n            demand[action[1]] = demand.get(action[1], 0) + 1\n    blocked = {crop for crop, n in demand.items() if n > seeds.get(crop, 0)}\n    for index, action in enumerate(actions):\n        if index > len(farm[\'hands\']):\n            break\n        if not isinstance(action, list) or not action:\n            continue\n        op = action[0]\n        pos = farm[\'farmer\'] if index == 0 else farm[\'hands\'][index - 1]\n        x, y = pos\n        while len(private[\'inventories\']) <= index:\n            private[\'inventories\'].append({})\n        inv = private[\'inventories\'][index]\n\n        def add(item, n=1):\n            inv[item] = inv.get(item, 0) + n\n\n        def take(item):\n            if inv.get(item, 0) < 1:\n                return False\n            inv[item] -= 1\n            if inv[item] == 0:\n                del inv[item]\n            return True\n\n        if op in moves:\n            dx, dy = moves[op]\n            new_pos = [x + dx, y + dy]\n            if 0 <= new_pos[0] < size and 0 <= new_pos[1] < size:\n                if index == 0:\n                    farm[\'farmer\'] = new_pos\n                else:\n                    farm[\'hands\'][index - 1] = new_pos\n            continue\n        tile = farm[\'tiles\'][y][x]\n        at_shed = (x, y) in access\n        if op == \'DROP\':\n            if at_shed:\n                for item, n in list(inv.items()):\n                    moved = min(n, max(0, 100 - sum(shed.values())))\n                    if moved > 0:\n                        shed[item] = shed.get(item, 0) + moved\n                    del inv[item]\n            continue\n        if op == \'PICKUP\':\n            if at_shed and len(action) >= 2:\n                item = action[1]\n                n = min(int(action[2]) if len(action) >= 3 else 1, shed.get(item, 0))\n                if n > 0:\n                    shed[item] -= n\n                    add(item, n)\n            continue\n        if op == \'PLACE\':\n            if len(action) < 2:\n                continue\n            item = action[1]\n            if (item in _PRO4_ANIMALS and isinstance(tile, dict)\n                    and tile.get(\'kind\') == _PRO4_ANIMALS[item][0]\n                    and \'animal\' not in tile):\n                if take(item):\n                    farm[\'tiles\'][y][x] = {\n                        \'kind\': _PRO4_ANIMALS[item][0], \'animal\': item,\n                        \'placed_day\': day, \'yield_units\': 0, \'consecutive_unfed\': 0,\n                        \'fed_today\': False, \'cared_today\': False,\n                        \'fertilizer_available\': False, \'pending_care_bonus\': 0,\n                    }\n            elif at_shed:\n                n = min(int(action[2]) if len(action) >= 3 else 1,\n                        inv.get(item, 0), max(0, 100 - sum(shed.values())))\n                if n > 0:\n                    inv[item] -= n\n                    if inv[item] == 0:\n                        del inv[item]\n                    shed[item] = shed.get(item, 0) + n\n            continue\n        if tile == \'LOCKED\':\n            continue\n        is_plant = isinstance(tile, dict) and tile.get(\'kind\') == \'PLANT\'\n        is_animal = isinstance(tile, dict) and \'animal\' in tile\n        if op == \'PLANT\' and len(action) >= 2:\n            crop = action[1]\n            if (tile is None and crop in _PRO4_CROPS and crop not in blocked\n                    and seeds.get(crop, 0) > 0):\n                _, max_age, _, ongoing = _PRO4_CROPS[crop]\n                seeds[crop] -= 1\n                farm[\'tiles\'][y][x] = {\n                    \'kind\': \'PLANT\', \'crop\': crop, \'planted_day\': day,\n                    \'watered_today\': False, \'consecutive_unwatered\': 1,\n                    \'yield_units\': 0 if ongoing else 1,\n                    \'max_lifespan_step\': -1 if ongoing else (day + max_age + 1) * 24,\n                    \'fertilized_until_day\': -1,\n                }\n        elif op == \'WATER\' and is_plant and not tile[\'watered_today\']:\n            tile[\'watered_today\'] = True\n            _, max_age, max_yield, ongoing = _PRO4_CROPS[tile[\'crop\']]\n            age = day - tile[\'planted_day\']\n            if not ongoing and (max_age + 1) // 2 <= age <= max_age:\n                bonus = 2 if tile[\'fertilized_until_day\'] >= day else 1\n                tile[\'yield_units\'] = min(max_yield, tile[\'yield_units\'] + bonus)\n        elif op == \'HARVEST\' and isinstance(tile, dict) and tile.get(\'yield_units\', 0) > 0:\n            if is_plant:\n                first_age, _, _, ongoing = _PRO4_CROPS[tile[\'crop\']]\n                if day - tile[\'planted_day\'] >= first_age:\n                    add(tile[\'crop\'], tile[\'yield_units\'])\n                    tile[\'yield_units\'] = 0\n                    if not ongoing:\n                        farm[\'tiles\'][y][x] = None\n            elif is_animal:\n                add(_PRO4_ANIMALS[tile[\'animal\']][1], tile[\'yield_units\'])\n                tile[\'yield_units\'] = 0\n        elif op == \'FERTILIZE\' and is_plant and take(\'FERTILIZER\'):\n            tile[\'fertilized_until_day\'] = max(tile.get(\'fertilized_until_day\', -1), day + 2)\n        elif op == \'DIG\' and tile is not None and not is_animal:\n            farm[\'tiles\'][y][x] = None\n        elif op in (\'BUILD_COOP\', \'BUILD_PASTURE\') and tile is None:\n            farm[\'tiles\'][y][x] = {\'kind\': op[6:]}\n        elif op == \'FEED\' and is_animal and not tile[\'fed_today\'] and take(\'WHEAT\'):\n            tile[\'fed_today\'] = True\n        elif op == \'COLLECT_FERTILIZER\' and is_animal and tile[\'fertilizer_available\']:\n            tile[\'fertilizer_available\'] = False\n            add(\'FERTILIZER\')\n        elif op == \'CARE\' and is_animal and not tile[\'cared_today\']:\n            tile[\'cared_today\'] = True\n    return result\n\n# Kaggle selects the last callable; preserve the tested policy unchanged.\ndef kaggle_agent(observation, configuration=None):\n    return agent(observation, configuration)\n', 'plant_deadline_fj2.py': '"""Repair impossible planting routes without displacing current valid work.\n\nExperimental adapter, not a submission. Keeps the reviewed reference\'s valid\nassignments and supply/delivery actions. Rematches only otherwise idle workers\nand workers assigned to planting that cannot start before its h21 cutoff.\nThis prevents a local route repair from taking away an already selected care\naction. Future daily outcomes and economic superiority remain unproven.\n"""\n\n\ndef install(reference):\n    original = reference.act_units\n\n    def act_units(obs, st, work):\n        previous = dict(st[\'targets\'])\n        actions, shed = original(obs, st, work)\n        farm, private = obs[\'farms\'][obs[\'player\']], obs[\'private\']\n        positions = [tuple(farm[\'farmer\']),*(tuple(p) for p in farm[\'hands\'])]\n        fixed = st[\'_fixed_units\']\n        hour, day = obs[\'hour\'], obs[\'day\']\n\n        def too_late(uid, target):\n            return (any(a[0] == \'PLANT\' for a in work.get(target,([],0))[0])\n                    and hour + reference.distance(positions[uid],target) >= 21)\n\n        invalid = {uid for uid,target in st[\'targets\'].items()\n                   if uid < len(positions) and uid not in fixed and too_late(uid,target)}\n        if not invalid: return actions, shed\n        workers = [uid for uid in range(len(positions)) if uid not in fixed\n                   and (uid in invalid or actions[uid] == [\'PASS\'])]\n        occupied = {target for uid,target in st[\'targets\'].items()\n                    if uid not in workers and uid not in fixed and uid < len(positions)}\n        occupied.update(positions[uid] for uid in fixed\n            if actions[uid][0] == \'PLACE\' and len(actions[uid]) > 1 and actions[uid][1] in reference.ANIMAL)\n        tiles = sorted(p for p in work if p not in occupied)\n        seeds = dict(private[\'seeds\'])\n        for uid,action in enumerate(actions):\n            if uid not in workers and action[0] == \'PLANT\': seeds[action[1]] -= 1\n        costs, commands = [], []\n        for uid in workers:\n            inv = private[\'inventories\'][uid] if uid < len(private[\'inventories\']) else {}\n            row, cmd = [], []\n            for target in tiles:\n                todo,value = work[target]; valid = []\n                for action in todo:\n                    op = action[0]\n                    if op == \'FERTILIZE\' and not inv.get(\'FERTILIZER\'): continue\n                    if op == \'FEED\' and not inv.get(\'WHEAT\'): continue\n                    if op == \'CARE\' and not farm[\'tiles\'][target[1]][target[0]].get(\'fed_today\') and not inv.get(\'WHEAT\'): continue\n                    if op in (\'BUILD_PASTURE\',\'BUILD_COOP\') and not inv.get(st[\'roles\'][target]): break\n                    if op == \'PLACE\' and not inv.get(action[1]): break\n                    if op == \'PLANT\' and seeds.get(action[1],0) <= 0: break\n                    valid.append(action)\n                distance = reference.distance(positions[uid],target)\n                deadline = 23 if day == 29 else 24\n                if day == 29 and hour + distance + len(valid) + reference.radius(target) + 1 > deadline:\n                    valid = [a for a in valid if a[0] == \'HARVEST\']\n                if (not valid or too_late(uid,target)\n                        or hour + distance + 1 + (reference.radius(target)+1 if day == 29 else 0) > deadline\n                        or (day == 29 and not any(a[0] == \'HARVEST\' for a in valid))):\n                    row.append(1000000.0);cmd.append([\'PASS\']);continue\n                cost = (distance + 0.15*len(valid) - reference.assignment_urgency(value,hour,day)\n                        + 6*(st[\'zones\'].get(target) != uid))\n                if positions[uid] == target: cost -= 2\n                if previous.get(uid) == target: cost -= 0.4\n                row.append(cost)\n                cmd.append(valid[0] if distance == 0 else reference.move(positions[uid],target))\n            costs.append(row+[50.0]*len(workers));commands.append(cmd)\n        matched = reference.minimum_assignment(costs)\n        for index,uid in enumerate(workers):\n            column = matched[index]\n            if column >= len(tiles) or costs[index][column] >= 100000.0:\n                actions[uid] = [\'PASS\'];st[\'targets\'].pop(uid,None);continue\n            action = commands[index][column]\n            if action[0] == \'PLANT\':\n                crop = action[1]\n                if seeds.get(crop,0) <= 0: action = [\'PASS\']\n                else: seeds[crop] -= 1\n            actions[uid] = action;st[\'targets\'][uid] = tiles[column]\n        return actions,shed\n\n    reference.act_units = act_units\n    return reference.agent\n', 'local_fertilization_fk.py': '"""Complete an existing fertilizer job locally instead of waiting for travel.\n\nExperimental adapter for the standard reviewed K Pro reference. Only an idle\nworker carrying fertilizer may take over an existing FERTILIZE task reserved\nto another worker who is moving. The moving worker\'s current action and all\nother actions remain intact. No target-memory rewrite or price forecast.\n"""\nimport copy\n\nMOVES={\'NORTH\',\'SOUTH\',\'EAST\',\'WEST\'}\n\n\ndef complete(obs,actions,st,work,*,project):\n    farm=obs[\'farms\'][obs[\'player\']]\n    positions=[tuple(farm[\'farmer\']),*(tuple(p) for p in farm[\'hands\'])]\n    owners={p:uid for uid,p in st[\'targets\'].items() if uid < len(actions)}\n    revised=list(actions)\n    baseline=None\n    for uid,(pos,action) in enumerate(zip(positions,revised)):\n        if action != [\'PASS\'] or uid in st.get(\'_fixed_units\',set()):continue\n        owner=owners.get(pos)\n        if owner is None or owner==uid or revised[owner][0] not in MOVES:continue\n        if owner in st.get(\'_fixed_units\',set()):continue\n        if not any(a[0]==\'FERTILIZE\' for a in work.get(pos,([],0))[0]):continue\n        if baseline is None:baseline=project(obs,revised)\n        tile=baseline[\'farms\'][obs[\'player\']][\'tiles\'][pos[1]][pos[0]]\n        if not isinstance(tile,dict) or tile.get(\'kind\')!=\'PLANT\':continue\n        if tile.get(\'fertilized_until_day\',-1)>=obs[\'day\']:continue\n        inventory=baseline[\'private\'][\'inventories\'][uid]\n        if inventory.get(\'FERTILIZER\',0)<=0:continue\n        trial=list(revised);trial[uid]=[\'FERTILIZE\']\n        after=project(obs,trial)\n        expected=copy.deepcopy(baseline)\n        expected[\'farms\'][obs[\'player\']][\'tiles\'][pos[1]][pos[0]][\'fertilized_until_day\']=obs[\'day\']+2\n        inv=expected[\'private\'][\'inventories\'][uid]\n        inv[\'FERTILIZER\']-=1\n        if inv[\'FERTILIZER\']==0:del inv[\'FERTILIZER\']\n        # Exact own-phase check guards canonical interactions and duplicated\n        # service, not just the final flag on the target plant.\n        if after != expected:continue\n        revised=trial;baseline=after\n    return revised\n\n\ndef install(reference):\n    original=reference.act_units\n\n    def act_units(obs,st,work):\n        actions,shed=original(obs,st,work)\n        return complete(obs,actions,st,work,project=reference.project_unit_phase),shed\n\n    reference.act_units=act_units\n    return reference.agent\n', 'wheat_accounting_fl.py': '"""Bound existing wheat purchases using actual post-unit own food inventory.\n\nDoes not change crop targets, selling policy, unit tasks, or other market orders.\nKeeps the reference\'s ordinary-day food target (unfed animals plus one third\nof planned herd), but counts pickup/harvest/feed exactly once. Never increases\na purchase. Terminal feeding rules are deliberately left to the reference.\nAn empty order is an ignored slot in the reviewed official market parser; it\npreserves simultaneous order indices instead of shifting subsequent orders.\n"""\n\n\ndef adjust(obs,action,state,*,project):\n    if obs[\'day\']>=28:return action\n    orders=action.get(\'market\',[])\n    buys=[i for i,o in enumerate(orders) if len(o)>=3 and o[0]==\'BUY_PRODUCT\'\n          and o[1]==\'WHEAT\' and o[2]>0]\n    # The reviewed policy emits one wheat buy. Multiple purchases require a\n    # fill-aware cash/market model; do not assume an earlier order succeeds.\n    if len(buys)!=1:return action\n    after=project(obs,[action[\'farmer\'],*action[\'hands\']])\n    private=after[\'private\'];farm=after[\'farms\'][obs[\'player\']]\n    food=private[\'shed\'].get(\'WHEAT\',0)+sum(i.get(\'WHEAT\',0) for i in private[\'inventories\'])\n    unfed=sum(1 for row in farm[\'tiles\'] for tile in row\n              if isinstance(tile,dict) and tile.get(\'animal\') and not tile.get(\'fed_today\'))\n    target=unfed+sum(state[\'herd\'].values())//3\n    sales=sum(o[2] for o in orders if len(o)>=3 and o[0]==\'SELL\' and o[1]==\'WHEAT\' and o[2]>0)\n    # Reserve all proposed sales, even if some might fail. No expected future\n    # harvest or future purchase from outside this action is credited.\n    need=max(0,target-food+sales)\n    result=list(orders);changed=False\n    for index in buys:\n        order=orders[index]\n        quantity=min(order[2],need)\n        need-=quantity\n        if quantity != order[2]:\n            result[index]=[\'BUY_PRODUCT\',\'WHEAT\',quantity] if quantity else []\n            changed=True\n    return dict(action,market=result) if changed else action\n\n\ndef install(reference):\n    original=reference.decide\n\n    def decide(obs,state):\n        action=original(obs,state)\n        return adjust(obs,action,state,project=reference.project_unit_phase)\n\n    reference.decide=decide\n    return reference.agent\n', 'feeding_intent_fm.py': '"""Align ordinary-day wheat purchases with the existing feeding policy.\n\nExperimental extension after FL. No new fasting decision is introduced.\nCounts intended feeds after own unit actions and keeps a reserve of at least\none wheat per currently fasting animal for the next feeding opportunity.\nThis is an inventory budget, not proof of future delivery or price profit.\n"""\n\n\ndef food_budget(obs, action, state, *, reference):\n    after = reference.project_unit_phase(obs, [action[\'farmer\'], *action[\'hands\']])\n    private = after[\'private\']\n    food = private[\'shed\'].get(\'WHEAT\', 0) + sum(i.get(\'WHEAT\', 0) for i in private[\'inventories\'])\n    intended = fasting = 0\n    for row in after[\'farms\'][obs[\'player\']][\'tiles\']:\n        for tile in row:\n            if not isinstance(tile, dict) or not tile.get(\'animal\') or tile[\'fed_today\']:\n                continue\n            tasks, _ = reference.animal_tasks(tile, obs[\'day\'], obs[\'market\'][\'prices\'], obs.get(\'town\', {}))\n            # Never reinterpret an already missed feeding as optional, even if\n            # a later policy changes its intent helper.\n            if [\'FEED\'] in tasks or tile.get(\'consecutive_unfed\', 0):\n                intended += 1\n            else:\n                fasting += 1\n    reserve = max(sum(state[\'herd\'].values())//3, fasting)\n    sales = sum(o[2] for o in action[\'market\'] if len(o) >= 3 and o[:2] == [\'SELL\',\'WHEAT\'] and o[2] > 0)\n    return dict(intended=intended, fasting=fasting, reserve=reserve, food=food,\n                target=intended+reserve, needed=max(0, intended+reserve+sales-food))\n\n\ndef adjust(obs, action, state, *, reference):\n    if obs[\'day\'] >= 28:\n        return action\n    orders = action[\'market\']\n    buys = [i for i, o in enumerate(orders) if len(o) >= 3 and o[:2] == [\'BUY_PRODUCT\',\'WHEAT\'] and o[2] > 0]\n    if len(buys) != 1:\n        return action\n    budget = food_budget(obs, action, state, reference=reference)\n    if not budget[\'fasting\']:\n        return action\n    index = buys[0]\n    quantity = min(orders[index][2], budget[\'needed\'])\n    if quantity == orders[index][2]:\n        return action\n    revised = list(orders)\n    revised[index] = [\'BUY_PRODUCT\',\'WHEAT\',quantity] if quantity else []\n    return dict(action, market=revised)\n\n\ndef install(reference):\n    original = reference.decide\n\n    def decide(obs, state):\n        return adjust(obs, original(obs, state), state, reference=reference)\n\n    reference.decide = decide\n    return reference.agent\n', 'expiry_rescue_fi.py': '"""Experimental local expiry rescue derived from a recorded K Pro 4 loss.\n\nNo opponent, seed or replay identifier enters the policy. This is not a\nstandalone submission and does not change the frozen submitted source.\n"""\n\n\ndef rescue(obs, action, *, project):\n    """Use an idle, already-present worker after planned local service.\n\nOnly the last action before an ordinary night is considered. The plant must\nalready be at its decay deadline for the next day. Reserve the entire carried\nstock and all proposed purchases before accepting a harvest; do not rely on a\nsale, free storage, or a final night after the game. The injected projection\nimplements the standard K Pro 24-turn/100-capacity own-unit phase.\n"""\n    day = obs[\'day\']\n    if day >= 29 or obs[\'hour\'] != 23:\n        return action\n    commands = [action.get(\'farmer\', [\'PASS\']), *action.get(\'hands\', [])]\n    farm = obs[\'farms\'][obs[\'player\']]\n    positions = [farm[\'farmer\'], *farm[\'hands\']]\n    next_step = (day + 1) * 24\n    candidates = []\n    for uid, command in enumerate(commands[:len(positions)]):\n        if command != [\'PASS\']:\n            continue\n        x, y = positions[uid]\n        tile = farm[\'tiles\'][y][x]\n        if (not isinstance(tile, dict) or \'crop\' not in tile\n                or not 0 <= tile.get(\'max_lifespan_step\', -1) <= next_step):\n            continue\n        # Earlier service can be followed by harvest. Later service cannot:\n        # it would act on the cleared tile and invalidate the existing plan.\n        if any(positions[j] == positions[uid] and commands[j][0] not in\n               (\'PASS\', \'NORTH\', \'SOUTH\', \'EAST\', \'WEST\')\n               for j in range(uid + 1, min(len(commands), len(positions)))):\n            continue\n        candidates.append(uid)\n    if not candidates:\n        return action\n    purchases = sum(max(0, int(order[2] if len(order) >= 3 else 1)) for order in action.get(\'market\', [])\n                    if isinstance(order, list) and len(order) >= 2\n                    and order[0] in (\'BUY_PRODUCT\', \'BUY_ANIMAL\'))\n    result = dict(action)\n    commands = [list(command) for command in commands]\n    for uid in candidates:\n        baseline = project(obs, commands)\n        trial_commands = [list(command) for command in commands]\n        trial_commands[uid] = [\'HARVEST\']\n        trial = project(obs, trial_commands)\n        old = baseline[\'private\'][\'inventories\'][uid]\n        new = trial[\'private\'][\'inventories\'][uid]\n        if sum(new.values()) <= sum(old.values()):\n            continue  # Already harvested, not mature, or otherwise no effect.\n        private = trial[\'private\']\n        total = sum(private[\'shed\'].values()) + sum(sum(inv.values()) for inv in private[\'inventories\'])\n        if total + purchases > 100:\n            continue\n        commands = trial_commands\n    result[\'farmer\'], result[\'hands\'] = commands[0], commands[1:]\n    return result\n\n\ndef make_agent(reference):\n    """Wrap a freshly loaded reference; leave its source and helpers intact."""\n    def agent(observation, configuration=None):\n        action = reference.agent(observation, configuration)\n        if configuration is not None and (\n                configuration.get(\'turnsPerDay\', 24) != 24\n                or configuration.get(\'shedCapacity\', 100) != 100\n                or configuration.get(\'episodeSteps\', 720) != 720):\n            return action\n        return rescue(observation, action, project=reference.project_unit_phase)\n    return agent\n'}
